const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
}

export default nextConfig
EOF
cat > lib/products.ts <<'EOF'
import { cacheLife, cacheTag } from 'next/cache'

const products = {
  lamp: { slug: 'lamp', name: 'Brass lamp', usd: 120 },
  vase: { slug: 'vase', name: 'Stone vase', usd: 80 },
}

export async function getProduct(slug: string, currency: string) {
  'use cache'
  cacheLife('hours')
  cacheTag(`product:${slug}`)
  await new Promise((resolve) => setTimeout(resolve, 120))
  const product = products[slug as keyof typeof products]
  if (!product) return null
  const rate = currency === 'EUR' ? 0.92 : 1
  return { ...product, price: `${currency} ${(product.usd * rate).toFixed(2)}` }
}

export async function getRelatedProducts(slug: string) {
  await new Promise((resolve) => setTimeout(resolve, 420))
  return Object.values(products).filter((product) => product.slug !== slug)
}
EOF
cat > "app/products/[slug]/page.tsx" <<'EOF'
import { notFound } from 'next/navigation'
import { Suspense } from 'react'
import { getProduct, getRelatedProducts } from '@/lib/products'

type Params = Promise<{ slug: string }>
type SearchParams = Promise<{ currency?: string }>

export default function ProductPage({
  params,
  searchParams,
}: {
  params: Params
  searchParams: SearchParams
}) {
  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense fallback={<p>Loading product…</p>}>
        <ProductDetails params={params} searchParams={searchParams} />
      </Suspense>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products…</p>}>
          <RelatedProducts params={params} />
        </Suspense>
      </section>
    </main>
  )
}

async function ProductDetails({
  params,
  searchParams,
}: {
  params: Params
  searchParams: SearchParams
}) {
  const { slug } = await params
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
    </>
  )
}

async function RelatedProducts({ params }: { params: Params }) {
  const { slug } = await params
  const related = await getRelatedProducts(slug)

  return related.map((item) => <p key={item.slug}>{item.name}</p>)
}
EOF
npm run build 2>&1 | tail -40

mkdir -p /tmp/chk && cat > /tmp/chk/check.mjs <<'EOF'
const base = 'http://localhost:3123'
for (const u of ['/products/lamp?currency=EUR', '/products/lamp', '/products/vase?currency=EUR', '/products/lamp?currency=EUR', '/products/nope']) {
  const t0 = Date.now()
  const res = await fetch(base + u)
  const reader = res.body.getReader()
  let first = null, html = ''
  const dec = new TextDecoder()
  for (;;) { const { done, value } = await reader.read(); if (done) break; if (first === null) { first = Date.now() - t0; var shell = dec.decode(value) } html += dec.decode(value) }
  const visible = html.replace(/<script[\s\S]*?<\/script>/g, '')
  const pick = (s) => [...s.matchAll(/<(h1|h2|p|a)[^>]*>([^<]*)<\/\1>/g)].map((m) => m[2]).join(' | ')
  console.log(`${u} -> ${res.status} first chunk ${first}ms, total ${Date.now() - t0}ms`)
  console.log('  shell:', pick(shell.replace(/<script[\s\S]*?<\/script>/g, '')))
  console.log('  final:', pick(visible), /noindex/.test(html) ? '[noindex]' : '')
}
EOF
(npx next start -p 3123 > /tmp/next.log 2>&1 &); sleep 4; node /tmp/chk/check.mjs; pkill -f "next start"; true

